        }

        if (modalidade.equals("RETIRADA_LOJA")) {
            return BigDecimal.ZERO;
        }

        if (modalidade.equals("MOTOBOY")) {
            return new BigDecimal("18.00");
        }

        return BigDecimal.ZERO;
    }

