import java.math.BigDecimal;
import java.math.RoundingMode;

public class test_debug {
    public static void main(String[] args) {
        BigDecimal totalPedido = new BigDecimal("409.70").add(new BigDecimal("15.60")).add(new BigDecimal("6.15"));
        System.out.println("Total Pedido: " + totalPedido);

        BigDecimal taxaMensal = new BigDecimal("0.0199");
        BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxaMensal);
        BigDecimal umMaisTaxaAlaN = umMaisTaxa.pow(6);

        BigDecimal denominador = umMaisTaxaAlaN.subtract(BigDecimal.ONE);
        BigDecimal numerador = taxaMensal.multiply(umMaisTaxaAlaN);

        System.out.println("(1 + taxa)^6 = " + umMaisTaxaAlaN);
        System.out.println("Denominador = " + denominador);
        System.out.println("Numerador = " + numerador);

        BigDecimal valorParcela = totalPedido.multiply(numerador).divide(denominador, 20, RoundingMode.HALF_EVEN);
        System.out.println("Valor Parcela (sem arredondar): " + valorParcela);

        valorParcela = valorParcela.setScale(2, RoundingMode.HALF_EVEN);
        System.out.println("Valor Parcela (arredondado): " + valorParcela);

        BigDecimal totalComJuros = valorParcela.multiply(new BigDecimal("6"));
        System.out.println("Total com Juros: " + totalComJuros);

        totalComJuros = totalComJuros.setScale(2, RoundingMode.HALF_EVEN);
        System.out.println("Total com Juros (arredondado): " + totalComJuros);

        BigDecimal ajuste = totalComJuros.subtract(totalPedido);
        System.out.println("Ajuste de Pagamento: " + ajuste.setScale(2, RoundingMode.HALF_EVEN));
    }
}
